import { PrivateIPError } from '@mintlify/common/ssrf';
import { createServer } from 'http';
import { fetchPublicAsset } from '../local-preview/export-fetch.js';
const loopbackLookup = (_hostname, options, callback) => options.all
    ? callback(null, [{ address: '127.0.0.1', family: 4 }])
    : callback(null, '127.0.0.1', 4);
describe('fetchPublicAsset', () => {
    let server;
    let origin;
    beforeAll(async () => {
        server = createServer((req, res) => {
            switch (req.url) {
                case '/icon.svg':
                    res.writeHead(200, { 'content-type': 'image/svg+xml' }).end('<svg/>');
                    return;
                case '/moved':
                    res.writeHead(302, { location: '/icon.svg' }).end();
                    return;
                case '/to-literal':
                    res.writeHead(302, { location: 'http://127.0.0.1/secret' }).end();
                    return;
                case '/to-metadata':
                    res.writeHead(302, { location: 'http://169.254.169.254/latest' }).end();
                    return;
                case '/loop':
                    res.writeHead(302, { location: '/loop' }).end();
                    return;
                case '/large':
                    res.writeHead(200).end(Buffer.alloc(2048));
                    return;
                case '/hang':
                    return;
                default:
                    res.writeHead(404).end('not found');
            }
        });
        await new Promise((resolve) => server.listen(0, '127.0.0.1', resolve));
        const address = server.address();
        if (!address || typeof address === 'string')
            throw new Error('server did not bind a port');
        origin = `http://assets.test:${address.port}`;
    });
    afterAll(async () => {
        server.closeAllConnections();
        await new Promise((resolve) => server.close(resolve));
    });
    it('downloads the body and content type', async () => {
        const asset = await fetchPublicAsset(`${origin}/icon.svg`, { lookup: loopbackLookup });
        expect(asset?.contentType).toBe('image/svg+xml');
        expect(asset?.body.toString()).toBe('<svg/>');
    });
    it('follows redirects', async () => {
        const asset = await fetchPublicAsset(`${origin}/moved`, { lookup: loopbackLookup });
        expect(asset?.body.toString()).toBe('<svg/>');
    });
    it('refuses redirects to private ip literals', async () => {
        await expect(fetchPublicAsset(`${origin}/to-literal`, { lookup: loopbackLookup })).resolves.toBeUndefined();
        await expect(fetchPublicAsset(`${origin}/to-metadata`, { lookup: loopbackLookup })).resolves.toBeUndefined();
    });
    it.each([
        'http://127.0.0.1/a',
        'http://[::1]/a',
        'http://[::ffff:7f00:1]/a',
        'file:///etc/passwd',
    ])('refuses %s without connecting', async (url) => {
        await expect(fetchPublicAsset(url)).resolves.toBeUndefined();
    });
    it('refuses hosts that resolve to private addresses', async () => {
        await expect(fetchPublicAsset('http://localhost/a')).rejects.toBeInstanceOf(PrivateIPError);
    });
    it('returns undefined for errors and redirect loops', async () => {
        await expect(fetchPublicAsset(`${origin}/missing`, { lookup: loopbackLookup })).resolves.toBeUndefined();
        await expect(fetchPublicAsset(`${origin}/loop`, { lookup: loopbackLookup })).resolves.toBeUndefined();
    });
    it('caps the response size', async () => {
        await expect(fetchPublicAsset(`${origin}/large`, { lookup: loopbackLookup, maxBytes: 1024 })).rejects.toThrow('asset exceeds 1024 bytes');
    });
    it('times out slow responses', async () => {
        await expect(fetchPublicAsset(`${origin}/hang`, { lookup: loopbackLookup, timeoutMs: 100 })).rejects.toThrow();
    });
});
